      list.innerHTML = visible.map(function(o){ return '<label class="excel-filter-option"><input type="checkbox" data-value="'+esc(o.value)+'" '+(temp.has(o.value)?'checked':'')+'> <span>'+esc(o.text)+'</span></label>'; }).join('');
