      table.innerHTML = '<thead><tr>' + cols.map(function(col,i){ return '<th draggable="true" data-index="'+i+'" data-key="'+esc(col[0])+'">' + esc(col[1]) + '</th>'; }).join('') + '</tr></thead><tbody><tr><td colspan="'+cols.length+'">No data available</td></tr></tbody>';
