/* --- userRequestSidebarRefreshPatchScript --- */

(function(){
  'use strict';

  function visible(el){
    return !!(el && el.offsetParent !== null && getComputedStyle(el).display !== 'none' && getComputedStyle(el).visibility !== 'hidden');
  }

  function activeTab(){
    const pairs = [
      ['gspn', document.getElementById('gspnPage')],
      ['sky', document.getElementById('skyPage')],
      ['profit', document.getElementById('profitPage')],
      ['cashTarget', document.getElementById('cashTargetPage')],
      ['preBooking', document.getElementById('preBookingPage')],
      ['returnCases', document.getElementById('returnCasesPage')],
      ['receivedDelivered', document.getElementById('receivedDeliveredPage')],
      ['dashboard', document.getElementById('dashboardPage')]
    ];
    for(const [tab,page] of pairs){
      if(page && page.style.display !== 'none' && visible(page)) return tab;
    }
    try{ return localStorage.getItem('serviceEyeActiveTab') || 'gspn'; }catch(e){ return 'gspn'; }
  }

  async function refreshActiveTab(){
    const tab = activeTab();
    try{
      if(tab === 'gspn' && typeof window.autoLoadGSPNFromGitHub === 'function') return await window.autoLoadGSPNFromGitHub(true);
      if(tab === 'sky' && typeof window.autoLoadSKYFromGitHub === 'function') return await window.autoLoadSKYFromGitHub(true);
      if(tab === 'profit' && typeof window.autoLoadProfitFromGitHub === 'function') return await window.autoLoadProfitFromGitHub(true);
      if(tab === 'cashTarget' && typeof window.loadCashTargetFromGitHub === 'function') return await window.loadCashTargetFromGitHub(true);
      if(tab === 'preBooking' && typeof window.loadPreBooking === 'function') return await window.loadPreBooking(true);
      if(tab === 'returnCases' && typeof window.loadReturnCases === 'function') return await window.loadReturnCases(true);
      if(tab === 'receivedDelivered' && typeof window.loadReceivedDelivered === 'function') return await window.loadReceivedDelivered(true);
      if(tab === 'dashboard' && typeof window.loadDashboardSources === 'function') return await window.loadDashboardSources(true);
      alert('Refresh Data is available for all GitHub data tabs.');
    }catch(err){

      alert('Refresh Data failed. Please check the console or try again.');
    }
  }

  function removeRequestedUploadButtons(){
    ['gspnPage','skyPage','profitPage'].forEach(function(pageId){
      const page = document.getElementById(pageId);
      if(!page) return;
      page.querySelectorAll('header .header-actions label.upload').forEach(function(label){
        label.style.setProperty('display','none','important');
        label.style.setProperty('visibility','hidden','important');
        label.style.setProperty('opacity','0','important');
        label.style.setProperty('pointer-events','none','important');
      });
    });
  }

  function hideHeaderRefreshButtons(){
    ['serviceV2Github_gspn','serviceV2Github_sky','serviceV2Github_profit'].forEach(function(id){
      const btn = document.getElementById(id);
      if(!btn) return;
      btn.style.setProperty('display','none','important');
      btn.style.setProperty('visibility','hidden','important');
      btn.style.setProperty('opacity','0','important');
      btn.style.setProperty('pointer-events','none','important');
    });
  }

  function ensureSidebarRefreshButton(){
    // Legacy top refresh button removed. The single supported button is codexGithubRefreshBtn in the sidebar bottom area.
    const legacyBlock = document.getElementById('sidebarRefreshDataBlock');
    if (legacyBlock) legacyBlock.remove();
    const legacyBtn = document.getElementById('sidebarRefreshDataBtn');
    if (legacyBtn) legacyBtn.remove();
  }

  function applyPatch(){
    removeRequestedUploadButtons();
    hideHeaderRefreshButtons();
    ensureSidebarRefreshButton();
  }

  window.serviceEyeEnableRefreshDataButton = function(){
    applyPatch();
  };
  window.serviceEyeDisableRefreshDataButton = function(){
    const block = document.getElementById('sidebarRefreshDataBlock');
    if(block) block.style.display = 'none';
  };

  if(document.readyState === 'loading') document.addEventListener('DOMContentLoaded', applyPatch);
  else applyPatch();
  window.addEventListener('load', function(){ setTimeout(applyPatch, 500); });
})();


